I CAN'T BE HAVING WITH THIS.

You want tests, do you? Not tests that make you FEEL good about yourself. Tests that'll find the truth hiding under all that clever code. Headology, that is. Making the code tell you what it REALLY does, not what it THINKS it does.

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Checkout } from './Checkout';

// Mocking is just making things believe what ain't so. Like headology.
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockCart = {
  items: [{ id: '1', name: 'Broomstick', price: 25.00 }],
  total: 25.00,
  clearCart: mockClearCart
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCart
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - Because I ain't dead and neither are bugs', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Broomstick', price: 25.00 }];
  });

  describe('Empty cart - seeing what's REALLY there', () => {
    it('shows empty state when cart has nothing', () => {
      mockCart.items = [];
      render(<Checkout />);
      expect(screen.getByRole('alert')).toHaveTextContent('Your cart is empty');
    });
  });

  describe('Happy path - the road that lies about having no potholes', () => {
    it('completes full checkout flow', async () => {
      mockProcessPayment.mockResolvedValue({ orderId: 'ORD-666' });
      const onComplete = vi.fn();

      render(<Checkout onComplete={onComplete} />);

      // Shipping - where you're sending the thing
      await user.type(screen.getByLabelText(/street address/i), '1 Lancre Lane');
      await user.type(screen.getByLabelText(/city/i), 'Lancre');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip/i), '12345');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment - never trust a card you can't see
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Esme Weatherwax');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review - seeing the truth
      expect(screen.getByText(/broomstick/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/ORD-666/)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-666');
    });
  });

  describe('Validation - finding the lies', () => {
    it('shows errors for empty shipping fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('rejects invalid ZIP codes', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip/i), 'WRONG');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Payment failures - when things go sideways', () => {
    it('displays error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      // ...navigate to review step...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent('Card declined');
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Loading states - patience is a virtue I ain't got', () => {
    it('disables buttons during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // ...navigate to review...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });
});
```

*taps finger on table*

There's no grays in testing. Either it passes or it doesn't. I don't hold with "sometimes works."
